func (o *GameServerBackup) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServer":
		rel, ok := retrieved.(*GameServer)
		if !ok {
			return fmt.Errorf("gameServerBackup cannot load %T as %q", retrieved, name)
		}

		o.R.GameServer = rel

		if rel != nil {
			rel.R.GameServerBackups = GameServerBackupSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("gameServerBackup has no relationship %q", name)
	}
}

