// LoadGameServer loads the gameServerBackup's GameServer into the .R struct
func (o *GameServerBackup) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServer = nil

	related, err := o.GameServer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.GameServerBackups = GameServerBackupSlice{o}

	o.R.GameServer = related
	return nil
}

// LoadGameServer loads the gameServerBackup's GameServer into the .R struct
func (os GameServerBackupSlice) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range gameServers {

			if !(o.GameServerID == rel.ID) {
				continue
			}

			rel.R.GameServerBackups = append(rel.R.GameServerBackups, o)

			o.R.GameServer = rel
			break
		}
	}

	return nil
}

type gameServerBackupJoins[Q dialect.Joinable] struct {
	typ        string
	GameServer modAs[Q, gameServerColumns]
}

func (j gameServerBackupJoins[Q]) aliasedAs(alias string) gameServerBackupJoins[Q] {
	return buildGameServerBackupJoins[Q](buildGameServerBackupColumns(alias), j.typ)
}

func buildGameServerBackupJoins[Q dialect.Joinable](cols gameServerBackupColumns, typ string) gameServerBackupJoins[Q] {
	return gameServerBackupJoins[Q]{
		typ: typ,
		GameServer: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.Name().As(to.Alias())).On(
						to.ID.EQ(cols.GameServerID),
					))
				}

				return mods
			},
		},
	}
}
